@aware([
    'transition' => false,
    'expanded' => false,
    'triggerId' => null,
    'contentId' => null,
])

@php
    $isExpanded = (bool) $expanded;
    $resolvedContentId = $contentId ?? 'accordion-content-'.str_replace('.', '', uniqid('', true));
@endphp

<div {{
    $attributes->class([
        'accordion__content',
        'overflow-hidden text-sm text-zinc-600 dark:text-zinc-400',
        $transition
        ? 'grid motion-safe:transition-[grid-template-rows,opacity] motion-safe:duration-200 motion-safe:ease-[cubic-bezier(0.16,1,0.3,1)]'
        : null,
        $transition && $isExpanded ? 'grid-rows-[1fr] opacity-100' : null,
        $transition && ! $isExpanded ? 'grid-rows-[0fr] opacity-0' : null,
        ! $transition && ! $isExpanded ? 'hidden' : null,
    ])->merge([
        'id' => $resolvedContentId,
        'role' => 'region',
        'aria-labelledby' => filled($triggerId) ? $triggerId : null,
        'data-accordion-content' => true,
        'data-state' => $isExpanded ? 'open' : 'closed',
        'hidden' => (! $transition && ! $isExpanded) ? true : null,
    ])
}}>
    <div class="accordion__content-inner min-h-0 px-4 pb-4" data-accordion-content-inner>{{ $slot }}</div>
</div>

@props([
    'exclusive' => false,
    'multiple' => null,
    'transition' => false,
    'variant' => null,
    'bordered' => false,
])

@php
    $isExclusive = $multiple === null
        ? (bool) $exclusive
        : ! (bool) $multiple;
@endphp

<div {{
    $attributes->class([
        'accordion',
        'w-full',
        $bordered ? 'rounded-xl border border-zinc-200 dark:border-zinc-800' : null,
    ])->merge([
        'data-accordion' => true,
        'data-accordion-exclusive' => $isExclusive ? 'true' : 'false',
        'data-accordion-transition' => $transition ? 'true' : 'false',
        'data-accordion-variant' => filled($variant) ? $variant : null,
    ])
}}>
    {{ $slot }}
</div>

@props([
    'value' => null,
    'heading' => null,
    'expanded' => false,
    'disabled' => false,
    'triggerId' => null,
    'contentId' => null,
])

@aware([
    'variant' => null,
    'transition' => false,
])

@php
    $itemValue = filled($value) ? (string) $value : 'accordion-item-'.str_replace('.', '', uniqid('', true));
    $isExpanded = (bool) $expanded;
    $isDisabled = (bool) $disabled;
    $itemId = 'accordion-'.str_replace('.', '', uniqid('', true));
    $triggerId ??= $itemId.'-trigger';
    $contentId ??= $itemId.'-content';
@endphp

<div {{
    $attributes->class([
        'accordion__item',
        'border-b border-zinc-200 last:border-b-0 dark:border-zinc-800',
    ])->merge([
        'data-accordion-item' => true,
        'data-accordion-value' => $itemValue,
        'data-state' => $isExpanded ? 'open' : 'closed',
        'data-accordion-disabled' => $isDisabled ? 'true' : null,
    ])
}}>
    @if (filled($heading))
        <x-ui::accordion.trigger> {{ $heading }} </x-ui::accordion.trigger>
        <x-ui::accordion.content> {{ $slot }} </x-ui::accordion.content>
    @else
        {{ $slot }}
    @endif
</div>

@aware([
    'variant' => null,
    'expanded' => false,
    'disabled' => false,
    'triggerId' => null,
    'contentId' => null,
])

@php
    $isExpanded = (bool) $expanded;
    $isDisabled = (bool) $disabled;
    $isReverse = $variant === 'reverse';
    $resolvedTriggerId = $triggerId ?? 'accordion-trigger-'.str_replace('.', '', uniqid('', true));
    $resolvedContentId = $contentId;
@endphp

<h3 class="accordion__heading m-0">
    <button
        type="button"
        {{
            $attributes->class([
                'accordion__trigger',
                'flex w-full items-center justify-between gap-3 px-4 py-3 text-left text-sm font-medium text-zinc-950',
                'transition-colors hover:bg-zinc-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-zinc-950/10',
                'disabled:pointer-events-none disabled:opacity-50',
                'dark:text-zinc-50 dark:hover:bg-zinc-900/60 dark:focus-visible:ring-zinc-300/20',
                $isReverse ? 'flex-row-reverse' : null,
            ])->merge([
                'id' => $resolvedTriggerId,
                'data-accordion-trigger' => true,
                'aria-expanded' => $isExpanded ? 'true' : 'false',
                'aria-controls' => filled($resolvedContentId) ? $resolvedContentId : null,
                'disabled' => $isDisabled ? true : null,
            ])
        }}
    >
        <span class="accordion__trigger-label min-w-0 flex-1">{{ $slot }}</span>
        <span
            class="accordion__trigger-icon [[data-state=open]_&]:rotate-180 inline-flex size-4 shrink-0 items-center justify-center text-zinc-500 transition-transform duration-200 dark:text-zinc-400"
            aria-hidden="true"
            data-accordion-icon
        >
            <x-ui::icon name="chevron-down" class="size-4" />
        </span>
    </button>
</h3>

/**
 * Stencil — accessible accordion (vanilla JS, no Alpine).
 */

const ACCORDION_SELECTOR = '[data-accordion]';
const ITEM_SELECTOR = '[data-accordion-item]';
const TRIGGER_SELECTOR = '[data-accordion-trigger]';
const CONTENT_SELECTOR = '[data-accordion-content]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initAccordions(root = document) {
    root.querySelectorAll(ACCORDION_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindAccordion(element);
    });
}

/**
 * @param {HTMLElement} accordion
 */
function bindAccordion(accordion) {
    syncItemWiring(accordion);

    accordion.addEventListener('click', (event) => {
        const trigger =
            event.target instanceof Element ? event.target.closest(TRIGGER_SELECTOR) : null;

        if (!(trigger instanceof HTMLButtonElement) || !accordion.contains(trigger)) {
            return;
        }

        if (trigger.disabled) {
            return;
        }

        const item = trigger.closest(ITEM_SELECTOR);

        if (!(item instanceof HTMLElement) || item.dataset.accordionDisabled === 'true') {
            return;
        }

        event.preventDefault();
        toggleItem(accordion, item);
    });
}

/**
 * @param {HTMLElement} accordion
 */
function syncItemWiring(accordion) {
    accordion.querySelectorAll(ITEM_SELECTOR).forEach((item) => {
        if (!(item instanceof HTMLElement)) {
            return;
        }

        const trigger = item.querySelector(TRIGGER_SELECTOR);
        const content = item.querySelector(CONTENT_SELECTOR);

        if (!(trigger instanceof HTMLElement) || !(content instanceof HTMLElement)) {
            return;
        }

        if (!trigger.id) {
            trigger.id = `accordion-trigger-${Math.random().toString(36).slice(2, 10)}`;
        }

        if (!content.id) {
            content.id = `accordion-content-${Math.random().toString(36).slice(2, 10)}`;
        }

        trigger.setAttribute('aria-controls', content.id);
        content.setAttribute('aria-labelledby', trigger.id);
        content.setAttribute('role', 'region');

        applyItemState(item, item.dataset.state === 'open');
    });
}

/**
 * @param {HTMLElement} accordion
 * @param {HTMLElement} item
 */
function toggleItem(accordion, item) {
    const willOpen = item.dataset.state !== 'open';
    const exclusive = accordion.dataset.accordionExclusive === 'true';

    if (willOpen && exclusive) {
        accordion.querySelectorAll(ITEM_SELECTOR).forEach((other) => {
            if (other instanceof HTMLElement && other !== item) {
                applyItemState(other, false);
            }
        });
    }

    applyItemState(item, willOpen);

    accordion.dispatchEvent(
        new CustomEvent('stencil:accordion:change', {
            bubbles: true,
            detail: {
                value: item.dataset.accordionValue ?? null,
                open: willOpen,
            },
        }),
    );
}

/**
 * @param {HTMLElement} item
 * @param {boolean} open
 */
function applyItemState(item, open) {
    const trigger = item.querySelector(TRIGGER_SELECTOR);
    const content = item.querySelector(CONTENT_SELECTOR);
    const accordion = item.closest(ACCORDION_SELECTOR);
    const transition =
        accordion instanceof HTMLElement && accordion.dataset.accordionTransition === 'true';

    item.dataset.state = open ? 'open' : 'closed';

    if (trigger instanceof HTMLElement) {
        trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
    }

    if (!(content instanceof HTMLElement)) {
        return;
    }

    content.dataset.state = open ? 'open' : 'closed';

    if (transition) {
        content.classList.toggle('grid-rows-[1fr]', open);
        content.classList.toggle('opacity-100', open);
        content.classList.toggle('grid-rows-[0fr]', !open);
        content.classList.toggle('opacity-0', !open);
        content.classList.remove('hidden');
        content.hidden = false;
    } else if (open) {
        content.hidden = false;
        content.classList.remove('hidden');
    } else {
        content.hidden = true;
        content.classList.add('hidden');
    }
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initAccordions(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initAccordions());
    } else {
        initAccordions();
    }
}
